// Extract clean domain from URL input
const inputUrl = $input.item.json.body.url || $input.item.json.url;

if (!inputUrl) {
  throw new Error('No URL provided');
}

// Remove protocol and trailing slashes
let domain = inputUrl
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/\/.*$/, '')
  .toLowerCase()
  .trim();

// Extract base domain (without subdomains except www)
const parts = domain.split('.');
if (parts.length > 2) {
  domain = parts.slice(-2).join('.');
}

return {
  json: {
    input_url: inputUrl,
    domain: domain,
    timestamp: new Date().toISOString(),
    analysis_id: Date.now().toString()
  }
};

// Process DataForSEO response and extract top keywords
const response = $input.item.json;

// Check if we have valid data
if (!response.tasks || !response.tasks[0] || !response.tasks[0].result) {
  return {
    json: {
      error: 'No keyword data found',
      domain: $('Extract Domain').item.json.domain,
      keywords: [],
      top_5_for_serp: [],
      stats: {
        total_keywords_tracked: 0,
        avg_position: 0,
        estimated_monthly_traffic: 0
      }
    }
  };
}

const results = response.tasks[0].result || [];

// Extract and format keywords
const keywords = results.slice(0, 20).map(item => {
  const keywordInfo = item.keyword_data?.keyword_info || {};
  const serpItem = item.ranked_serp_element?.serp_item || {};

  return {
    keyword: item.keyword,
    search_volume: keywordInfo.search_volume || 0,
    competition: keywordInfo.competition || 0,
    cpc: keywordInfo.cpc || 0,
    position: serpItem.rank_group || 999,
    url: serpItem.url || '',
    estimated_traffic: Math.round((keywordInfo.search_volume || 0) * 0.3 / (serpItem.rank_group || 20))
  };
}).filter(k => k.search_volume > 0);

// Get top 5 for SERP analysis
const top5Keywords = keywords.slice(0, 5).map(k => k.keyword);

// Calculate some stats
const totalEstimatedTraffic = keywords.reduce((sum, k) => sum + k.estimated_traffic, 0);
const avgPosition = keywords.length > 0 
  ? Math.round(keywords.reduce((sum, k) => sum + k.position, 0) / keywords.length * 10) / 10
  : 0;

return {
  json: {
    domain: $('Extract Domain').item.json.domain,
    total_keywords_found: results.length,
    top_keywords: keywords,
    top_5_for_serp: top5Keywords,
    stats: {
      total_keywords_tracked: keywords.length,
      avg_position: avgPosition,
      estimated_monthly_traffic: totalEstimatedTraffic
    }
  }
};

// Process SERP data to extract competitor domains
const allItems = $input.all();
const domainCount = {};
const serpFeatures = {};
const targetDomain = $('Extract Domain').item.json.domain;

allItems.forEach(item => {
  const response = item.json;

  if (!response.tasks || !response.tasks[0] || !response.tasks[0].result) {
    return;
  }

  const result = response.tasks[0].result[0];
  if (!result) return;

  const keyword = result.keyword;

  // Extract domains from organic results
  const items = result.items || [];
  items.forEach(serpItem => {
    if (serpItem.type === 'organic') {
      try {
        const url = new URL(serpItem.url);
        let domain = url.hostname.replace(/^www\./, '');

        // Extract base domain
        const parts = domain.split('.');
        if (parts.length > 2) {
          domain = parts.slice(-2).join('.');
        }

        // Skip our own domain and generic sites
        const skipDomains = [targetDomain, 'wikipedia.org', 'amazon.com', 'youtube.com', 'reddit.com'];
        if (!skipDomains.includes(domain)) {
          domainCount[domain] = (domainCount[domain] || 0) + 1;
        }
      } catch (e) {
        // Skip invalid URLs
      }
    }
  });

  // Extract SERP features
  if (!serpFeatures[keyword]) {
    serpFeatures[keyword] = {
      featured_snippet: null,
      people_also_ask: [],
      related_searches: []
    };
  }

  items.forEach(item => {
    if (item.type === 'featured_snippet') {
      serpFeatures[keyword].featured_snippet = item.description || item.text;
    }
    if (item.type === 'people_also_ask') {
      item.items?.forEach(q => {
        if (q.title) serpFeatures[keyword].people_also_ask.push(q.title);
      });
    }
    if (item.type === 'related_searches') {
      item.items?.forEach(s => {
        if (s.title) serpFeatures[keyword].related_searches.push(s.title);
      });
    }
  });
});

// Sort competitors by frequency
const competitors = Object.entries(domainCount)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([domain, count]) => ({
    domain,
    appearances: count,
    relevance_score: Math.round((count / allItems.length) * 100)
  }));

return {
  json: {
    target_domain: targetDomain,
    competitors_found: competitors,
    top_competitor: competitors[0]?.domain || null,
    serp_features: serpFeatures,
    analysis_metadata: {
      keywords_analyzed: allItems.length,
      total_serp_positions_checked: allItems.length * 10
    }
  }
};

// Process competitor keywords
const response = $input.item.json;
const myKeywords = $('Process Keywords').item.json.top_keywords.map(k => k.keyword.toLowerCase());

if (!response.tasks || !response.tasks[0] || !response.tasks[0].result) {
  return {
    json: {
      competitor_domain: $('Analyze SERP').item.json.top_competitor,
      competitor_keywords: [],
      keyword_gaps: []
    }
  };
}

const results = response.tasks[0].result || [];

// Extract competitor keywords
const competitorKeywords = results.map(item => {
  const keywordInfo = item.keyword_data?.keyword_info || {};
  const serpItem = item.ranked_serp_element?.serp_item || {};

  return {
    keyword: item.keyword,
    search_volume: keywordInfo.search_volume || 0,
    competition: keywordInfo.competition || 0,
    cpc: keywordInfo.cpc || 0,
    competitor_position: serpItem.rank_group || 999
  };
});

// Find keyword gaps
const gaps = competitorKeywords
  .filter(ck => !myKeywords.includes(ck.keyword.toLowerCase()))
  .filter(ck => ck.search_volume >= 100)
  .slice(0, 20)
  .map(k => ({
    ...k,
    opportunity_score: Math.round(k.search_volume / Math.max(k.competition * 100, 1))
  }))
  .sort((a, b) => b.opportunity_score - a.opportunity_score);

return {
  json: {
    competitor_domain: $('Analyze SERP').item.json.top_competitor,
    competitor_keywords: competitorKeywords,
    keyword_gaps: gaps
  }
};

// No competitor - create empty data
return {
  json: {
    competitor_domain: 'None found',
    competitor_keywords: [],
    keyword_gaps: []
  }
};

// Prepare comprehensive data for Claude
const keywordData = $('Process Keywords').item.json;
const serpData = $('Analyze SERP').item.json;
const competitorData = $input.item.json;
const domain = $('Extract Domain').item.json.domain;

const prompt = `# SEO Strategy Analysis

You are an expert SEO strategist. Create a comprehensive, actionable report for a small business owner.

## Target Website
**Domain:** ${domain}

## Current Performance
**Keywords Ranking:** ${keywordData.stats.total_keywords_tracked}  
**Average Position:** ${keywordData.stats.avg_position}  
**Estimated Monthly Traffic:** ${keywordData.stats.estimated_monthly_traffic} visitors

### Top Keywords:
${keywordData.top_keywords.slice(0, 10).map(k => `- ${k.keyword} (Vol: ${k.search_volume}, Pos: ${k.position})`).join('\n')}

## Competitors Found
${serpData.competitors_found.map(c => `- ${c.domain} (appears ${c.appearances}x in top results)`).join('\n')}

## Keyword Opportunities (Gaps)
${competitorData.keyword_gaps.slice(0, 10).map(k => `- ${k.keyword} (Vol: ${k.search_volume}, Opportunity Score: ${k.opportunity_score})`).join('\n')}

## SERP Features Detected
${Object.entries(serpData.serp_features).map(([kw, features]) => {
  let result = `**${kw}:**`;
  if (features.featured_snippet) result += '\n  - Featured Snippet present';
  if (features.people_also_ask.length) result += `\n  - PAA: ${features.people_also_ask.slice(0, 3).join(', ')}`;
  return result;
}).join('\n\n')}

---

# Your Task:

Create a clear, actionable SEO strategy report with:

## 1. Executive Summary
Brief overview (2-3 sentences) of current situation and biggest opportunity.

## 2. Performance Analysis
- Current strengths
- Main weaknesses
- Quick assessment

## 3. Top 10 Opportunity Keywords
Table format:
| Keyword | Volume | Competition | Why Important | Action |

Focus on quick wins with good volume and manageable competition.

## 4. Content Recommendations (3-5 ideas)
For each:
- Suggested title
- Target keywords
- H2/H3 outline
- Estimated word count
- Priority level

## 5. SERP Features Strategy
- Which features to target
- Specific recommendations

## 6. Action Checklist
5-10 concrete, prioritized steps for a non-expert.

## 7. Expected Results
- Traffic projection (conservative)
- Realistic timeline

**Guidelines:**
- Clear, jargon-free language
- Actionable, specific recommendations
- Focus on realistic quick wins
- Use provided data (don't invent numbers)
- Format in clean Markdown
`;

return {
  json: {
    prompt: prompt,
    raw_data: {
      domain,
      keywords: keywordData,
      serp: serpData,
      competitor: competitorData
    }
  }
};

// Extract Claude's response
const response = $input.item.json;

if (!response.content || !response.content[0]) {
  throw new Error('No response from Claude');
}

const reportContent = response.content[0].text;

return {
  json: {
    report: reportContent,
    domain: $('Extract Domain').item.json.domain,
    timestamp: new Date().toISOString()
  }
};

// Prepare data for Google Sheets
const keywordData = $('Process Keywords').item.json;
const competitorData = $('Merge All').item.json;
const domain = $('Extract Domain').item.json.domain;

// Format keywords for sheet
const keywordRows = keywordData.top_keywords.map(k => ({
  Domain: domain,
  Keyword: k.keyword,
  'Search Volume': k.search_volume,
  Competition: k.competition,
  CPC: k.cpc,
  Position: k.position,
  'Est. Traffic': k.estimated_traffic,
  Date: new Date().toISOString().split('T')[0]
}));

// Format gaps for sheet
const gapRows = competitorData.keyword_gaps?.slice(0, 15).map(k => ({
  Domain: domain,
  Keyword: k.keyword,
  'Search Volume': k.search_volume,
  Competition: k.competition,
  'Opportunity Score': k.opportunity_score,
  'Competitor Position': k.competitor_position,
  Date: new Date().toISOString().split('T')[0]
})) || [];

return [
  ...keywordRows.map(row => ({ json: { ...row, Type: 'Current' } })),
  ...gapRows.map(row => ({ json: { ...row, Type: 'Opportunity' } }))
];

